from django.urls import include, path
from rest_framework.routers import DefaultRouter
from .views.task import TaskViewSet
from .views.auth_api import CsrfApi, MeApi, LoginApi, LogoutApi, RegisterApi

router = DefaultRouter()
router.register('tasks', TaskViewSet, basename='api-task')

urlpatterns = [
  path('api/', include(router.urls)),
  path('api/auth/csrf/', CsrfApi.as_view(), name='api-csrf'),
  path('api/auth/me/', MeApi.as_view(), name='api-me'),
  path('api/auth/login/', LoginApi.as_view(), name='api-login'),
  path('api/auth/logout/', LogoutApi.as_view(), name='api-logout'),
  path('api/auth/register/', RegisterApi.as_view(), name='api-register'),
]
